// Payload real de Noova (imagen). En n8n el POST suele llegar en .body;
// si tu instancia lo pone en la raíz, el fallback cubre ambos casos.
const item = $input.item.json;
const body = item.body && typeof item.body === "object" ? item.body : item;

const conversationId = body.conversation_id;
const callbackUrl = body.callback_url;
const event = body.event;
const contactPhone = body.contact && body.contact.phone;
const contactLabel = body.contact && body.contact.label;
const imageUrl = body.image && body.image.url;
const analysis = String((body.image && body.image.analysis) || (body.message && body.message.text) || "");

if (!conversationId || !callbackUrl) {
  throw new Error("Faltan conversation_id o callback_url. Revisa que el conector de Noova esté pegado a la URL de producción de este webhook.");
}

// --- Tu lógica de negocio va aquí ---
// Noova ya analizó la imagen: usa `analysis`. Solo descarga `imageUrl` si necesitas el archivo.
const hayDano = /da[ñn]o|roto|defecto|quebrado|rayado/i.test(analysis);

const replyText = hayDano
  ? "Lamentamos el inconveniente. Ya registramos tu caso y un asesor te contactará para gestionar la garantía."
  : "¡Gracias por la imagen! Ya la registramos. En un momento un asesor te comparte más detalles.";

return {
  event,
  conversation_id: conversationId,
  callback_url: callbackUrl,
  contact_phone: contactPhone || "",
  contact_label: contactLabel || "",
  image_url: imageUrl || "",
  analysis,
  reply_text: replyText
};
